typedef struct { int (*save)(const user_t *); bool (*find)(int id, user_t *out); } user_repo_t;

static user_t store[64];
static size_t count;

static int fake_save(const user_t *u) { store[count++] = *u; return 0; }
static bool fake_find(int id, user_t *out) {
    for (size_t i = 0; i < count; i++)
        if (store[i].id == id) { *out = store[i]; return true; }
    return false;
}
user_repo_t fake_repo(void) { return (user_repo_t){ fake_save, fake_find }; }
